// Original implementation of YIN's difference / CMND / threshold / interpolation
// stages (de Cheveigné & Kawahara, JASA 2002, doi:10.1121/1.1458024).
// Periodicity confidence is a heuristic, not a calibrated probability.
function createYin({ minFrequency = 60, maxFrequency = 2000, threshold = .12, minRms = .006 } = {}) {
  let difference = new Float64Array(0);
  return (samples, sampleRate) => {
    const empty = { frequencyHz: null, confidence: 0, rms: 0, clipped: false };
    if (!Number.isFinite(sampleRate) || sampleRate <= 0 || samples.length < 32) return empty;
    let sum = 0, squares = 0, peak = 0;
    for (const sample of samples) {
      if (!Number.isFinite(sample)) return empty;
      sum += sample; squares += sample * sample; peak = Math.max(peak, Math.abs(sample));
    }
    const rms = Math.sqrt(Math.max(0, squares / samples.length - (sum / samples.length) ** 2));
    const result = { ...empty, rms, clipped: peak >= .98 };
    if (rms < minRms) return result;
    const windowSize = Math.floor(samples.length / 2);
    const maxLag = Math.min(Math.ceil(sampleRate / minFrequency), windowSize - 2);
    const minLag = Math.max(2, Math.floor(sampleRate / maxFrequency));
    if (maxLag <= minLag) return result;
    if (difference.length < maxLag + 2) difference = new Float64Array(maxLag + 2);
    difference[0] = 1;
    let cumulative = 0;
    for (let lag = 1; lag <= maxLag + 1; lag++) {
      let value = 0;
      for (let i = 0; i < windowSize; i++) {
        const delta = samples[i] - samples[i + lag]; value += delta * delta;
      }
      cumulative += value;
      difference[lag] = cumulative > 0 ? value * lag / cumulative : 1;
    }
    for (let lag = minLag; lag <= maxLag; lag++) {
      if (difference[lag] >= threshold) continue;
      while (lag < maxLag && difference[lag + 1] < difference[lag]) lag++;
      const a = difference[lag - 1], b = difference[lag], c = difference[lag + 1];
      const denominator = a - 2 * b + c;
      const offset = denominator ? Math.max(-1, Math.min(1, .5 * (a - c) / denominator)) : 0;
      const frequencyHz = sampleRate / (lag + offset);
      // Allow interpolation's small boundary error without snapping the estimate.
      if (frequencyHz < minFrequency * .995 || frequencyHz > maxFrequency * 1.005) return result;
      return { ...result, frequencyHz, confidence: Math.max(0, Math.min(1, 1 - b)) };
    }
    // No global-minimum fallback: noise must not become a confident fake pitch.
    return result;
  };
}

